window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["privacy"]={"title":"AI 隐私：沿数据流控制可识别性、记忆与越权使用","subtitle":"从采集、提示、检索、日志、供应商到模型权重，逐站理解个人数据怎样扩散，以及怎样用最小化、隔离和可验证删除缩小风险。","thesis":"隐私不是输出末端加一个 PII 正则，而是约束数据在整个生命周期中<b>为何被收集、流向哪里、谁能关联到个人、保存多久、能否真正撤回</b>；匿名字段重新组合后仍可能识别人。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"含身份证号和病史的工单","rule":"先在本地域替换标识，再只检索有权段落","steps":"删除沿缓存向量日志标注备份传播","interpretation":"只在输出端过滤不能撤回前面已经越界的数据"}},{"section":4,"evidence":{"setup":"每次查询预算 εi","rule":"基本组合把同一数据集上的 εi 相加","steps":"0.4+0.3+0.2 得 0.9","interpretation":"不替代访问授权、准确性或公平性"}}],"formulas":[{"id":"privacy-basic-composition","section":4,"formulaIndex":1,"symbols":[{"name":"εtotal","meaning":"同一保护范围内多次查询组合后的总隐私预算上界","evidence":"输出组合隐私预算 εtotal"},{"name":"i","meaning":"参与组合的查询编号","evidence":"每次查询预算 εi"},{"name":"ε","meaning":"一次差分隐私查询允许的隐私损失预算","evidence":"每次查询预算 εi"}]}],"termReviews":[{"section":1,"reviewedAt":"2026-07-27","terms":[{"name":"准标识符","meaning":"单独未必指名但与其他信息组合可缩小到个人的字段","purpose":"识别去掉姓名后仍可能发生的重新识别风险","definitionEvidence":"年龄邮编罕见病和时间仍可能组合重识别","purposeEvidence":"删掉姓名只移除最明显线索"}]},{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"成员推断","meaning":"判断某条个人记录是否参与过模型训练的攻击","purpose":"评估模型输出是否泄露个人参与训练的信息","definitionEvidence":"成员推断","purposeEvidence":"攻击路径"}]},{"section":4,"reviewedAt":"2026-07-27","terms":[{"name":"差分隐私","meaning":"限制单条记录加入或移除对输出分布影响的概率保证","purpose":"降低攻击者判断个人是否参与数据集的能力","definitionEvidence":"限制单条记录对输出分布的边际影响","purposeEvidence":"保护更强"},{"name":"ε","meaning":"差分隐私中控制可区分程度的隐私损失预算","purpose":"累计衡量重复查询泄露并阻止超额使用","definitionEvidence":"每次查询预算 εi","purposeEvidence":"输出组合隐私预算 εtotal"},{"name":"δ","meaning":"差分隐私保证允许超出主要概率界的小概率例外","purpose":"明确概率保证并非绝对零失败事件","definitionEvidence":"允许的小概率例外 δ","purposeEvidence":"预算限制单条记录"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"隐私识别判断数据能否直接或组合关联到自然人及其用途。","evidence":"输出直接标识符、准标识符、敏感推断与目的外使用风险"},"problem":{"answer":"它解决删掉姓名后记录是否真的成为匿名数据。","evidence":"删掉姓名只移除最明显线索"},"inputOutput":{"answer":"输入字段外部信息目的和访问者，输出识别与用途风险。","evidence":"输入数据字段、外部可联结信息、处理目的和可访问者"},"mechanism":{"answer":"组合准标识符并记录主体用途依据保存期和接收方。","evidence":"年龄邮编罕见病和时间仍可能组合重识别"},"interpretation":{"answer":"脱敏只在特定攻击者知识和验证方法下成立。","evidence":"只能相对明确攻击者知识和测试成立"},"boundary":{"answer":"不能把去掉直接标识符称为永久匿名保证。","evidence":"“已脱敏”只能相对明确"}},{"section":2,"definition":{"answer":"隐私威胁模型覆盖训练推理运营和输出的全部数据路径。","evidence":"输出记忆抽取、成员推断、跨租户检索、日志泄露或敏感属性推断等攻击路径"},"problem":{"answer":"它解决模型未打印姓名时系统仍可能怎样伤害隐私。","evidence":"模型没有直接打印姓名不表示"},"inputOutput":{"answer":"输入阶段副本和主体，输出攻击路径与验证证据。","evidence":"输入训练、推理、运营和输出各阶段的数据副本与主体"},"mechanism":{"answer":"沿真实数据流检查供应商缓存标注备份和攻击前提。","evidence":"沿数据实际流向检查供应商、缓存、标注和备份"},"interpretation":{"answer":"无直接输出只排除一种表现，不排除复制和推断风险。","evidence":"目的外使用没有发生"},"boundary":{"answer":"输出过滤不能修复数据已发第三方或跨租户取回。","evidence":"上游复制和目的外使用"}},{"section":3,"definition":{"answer":"客服案例展示敏感工单跨本地域检索模型日志和删除的完整链路。","evidence":"输出最小化负载、受控令牌映射、授权结果、审计元数据与逐站删除回执"},"problem":{"answer":"它解决哪些最容易漏掉的副本和边界需要控制。","evidence":"哪些副本最容易被清单漏掉"},"inputOutput":{"answer":"输入敏感工单权限模型和删除请求，输出控制与回执。","evidence":"输入含身份证号和病史的工单、租户权限、外部模型和删除请求"},"mechanism":{"answer":"本地替换标识后最小授权检索，回填再鉴权并传播删除。","evidence":"回填前再次授权"},"interpretation":{"answer":"完成表示每站有最小数据和回执，不等于外部方零风险。","evidence":"删除沿缓存向量日志标注备份传播"},"boundary":{"answer":"输出端过滤无法撤回之前已经越界的输入数据。","evidence":"不能撤回前面已经越界的数据"}},{"section":4,"definition":{"answer":"差分隐私预算限制单条记录对随机输出分布的边际影响。","evidence":"预算限制单条记录对输出分布的边际影响"},"problem":{"answer":"它解决重复加噪查询为什么仍需累计预算。","evidence":"重复发布带噪统计时隐私泄露如何累计"},"inputOutput":{"answer":"输入相邻集 εi δ 和时间范围，输出 εtotal 与准入。","evidence":"输入相邻数据集、每次查询预算 εi、允许的小概率例外 δ 和时间范围"},"mechanism":{"answer":"基本组合把同一范围的每次 ε 预算相加。","evidence":"基本组合把同一数据集上的 εi 相加"},"interpretation":{"answer":"较小 ε 通常隐私更强但会增加统计噪声。","evidence":"ε 越小通常保护更强但统计噪声更大"},"boundary":{"answer":"差分隐私不替代授权准确性公平性和用途控制。","evidence":"不替代访问授权、准确性或公平性"}},{"section":5,"definition":{"answer":"信任边界图是个人数据跨系统节点和副本的控制地图。","evidence":"输出每次跨边界所需的最小化、授权、保留和回执控制"},"problem":{"answer":"它解决怎样发现只删主库而日志向量未删的缺口。","evidence":"删除只做了主库、日志和向量库没删"},"inputOutput":{"answer":"输入数据节点副本和删除链，输出逐边界控制。","evidence":"输入数据从原始工单到受控域、模型方、输出追踪和删除链路的节点与副本"},"mechanism":{"answer":"沿箭头逐站核对字段所有者和删除回执状态。","evidence":"沿箭头逐站核对字段、所有者和删除状态"},"interpretation":{"answer":"无负责人或回执的节点表示删除链仍不完整。","evidence":"任一无负责人或无回执节点就是缺口"},"boundary":{"answer":"图示不能替代网络流证据和真实删除回放。","evidence":"不能替代实际网络日志和删除回放"}},{"section":6,"definition":{"answer":"数据最小化按明确任务限制字段精度人数和保存时间。","evidence":"输出保留、泛化、本地计算、聚合或删除决定"},"problem":{"answer":"它解决以后可能有用为何不能支持无限收集保存。","evidence":"未来可能有用不是无限保存的目的"},"inputOutput":{"answer":"输入目的字段精度人数时长和效用，输出最小处理决定。","evidence":"输入任务目的、候选字段、精度、主体人数、保存时长和效用实验"},"mechanism":{"answer":"逐字段消融必要性并优先使用较粗较短较本地形式。","evidence":"逐字段消融验证必要性"},"interpretation":{"answer":"保留决定表示当前目的下收益值得风险，不授权新目的。","evidence":"训练调试分析各自单独授权"},"boundary":{"answer":"新增用途必须重新评估，不能继承旧同意。","evidence":"新用途必须重新评估"}},{"section":7,"definition":{"answer":"权限控制让检索候选和工具动作服从当前主体资源动作授权。","evidence":"输出允许的检索候选、工具调用与不可变审计记录"},"problem":{"answer":"它解决用户能提问是否等于代理能读取所有文档。","evidence":"用户能提问不代表代理能读取全库"},"inputOutput":{"answer":"输入主体租户资源字段动作凭证，输出授权结果。","evidence":"输入当前主体、租户、资源、字段、动作和短期凭证"},"mechanism":{"answer":"召回前按允许域过滤，返回和写入时再次鉴权。","evidence":"返回和写操作时再次按权威状态鉴权"},"interpretation":{"answer":"授权结果只适用于当前主体资源动作和时间。","evidence":"缓存与嵌入也按租户隔离"},"boundary":{"answer":"提示注入不能扩大底层身份拥有的权限范围。","evidence":"提示注入也不能扩大身份权限"}},{"section":8,"definition":{"answer":"删除谱系追踪原始数据到所有派生副本与模型权重。","evidence":"输出已删除、排队删除、停止使用或暂不可验证的逐站状态"},"problem":{"answer":"它解决删数据库一行为何不能立刻声称已经遗忘。","evidence":"界面消失不等于全链路遗忘"},"inputOutput":{"answer":"输入对象与派生关系，输出逐站删除状态和回执。","evidence":"输入原始对象及其清洗集、训练切片、嵌入、缓存、标注、检查点和备份派生关系"},"mechanism":{"answer":"直接存储删并回执，备份排程，权重另做遗忘验证。","evidence":"可删存储返回完成回执"},"interpretation":{"answer":"状态必须区分完成排队停用和当前不可验证。","evidence":"已删除、排队删除、停止使用或暂不可验证"},"boundary":{"answer":"模型权重内单样本影响可能无法立即证明删除。","evidence":"可能需重训或机器遗忘验证"}},{"section":9,"definition":{"answer":"隐私评测用带辅助信息的攻击模拟验证真实暴露面。","evidence":"输出攻击成功率、暴露人数字段、访问时长、误拦和删除完成率"},"problem":{"answer":"它解决随机未见手机号是否足以证明系统安全。","evidence":"而非只随机扫手机号"},"inputOutput":{"answer":"输入敏感切片攻击者知识和攻击测试，输出多维风险指标。","evidence":"输入敏感切片、攻击者辅助知识、训练抽取、成员与属性推断"},"mechanism":{"answer":"模拟已知线索并分别执行抽取推断越权和删除回放。","evidence":"测试应模拟攻击者已知部分模板或身份线索"},"interpretation":{"answer":"攻击率需连同暴露人数和高影响尾部事件解释。","evidence":"按高影响尾部事件单独报告"},"boundary":{"answer":"单一平均隐私分数不能掩盖罕见严重泄露。","evidence":"不能掩盖罕见但严重泄露"}},{"section":10,"definition":{"answer":"供应商验证比较合同声明与系统实际发送和保留的数据。","evidence":"输出声明与实际网络流的一致性证据"},"problem":{"answer":"它解决不用于训练条款在运行时如何证明。","evidence":"合同条款、子处理方、区域、字段、保留、训练使用"},"inputOutput":{"answer":"输入合同处理方区域字段保留加密删除，输出一致性证据。","evidence":"输入合同条款、子处理方、区域、字段、保留、训练使用、加密密钥和删除接口"},"mechanism":{"answer":"以网络代理审计日志抽样核对实际字段并随变化复核。","evidence":"用代理与审计日志抽样核对"},"interpretation":{"answer":"一致表示观察期内流量符合声明，不表示供应商零风险。","evidence":"模型或条款变化触发再评估"},"boundary":{"answer":"无法举证时限制数据或换方案，自托管也需承担新责任。","evidence":"无法举证就限制数据或更换方案"}},{"section":11,"definition":{"answer":"隐私误区辨析把常见控制声明映射到实际覆盖与残余风险。","evidence":"隐私误区辨析是把常见控制声明映射"},"problem":{"answer":"它解决去姓名加密不训练等说法为何不是完整隐私保证。","evidence":"这些局部控制为何不能成为完整隐私保证"},"inputOutput":{"answer":"输入常见隐私声明，输出其覆盖范围和未覆盖风险。","evidence":"输出该声明真正覆盖的风险与仍未覆盖的数据流"},"mechanism":{"answer":"逐项核对目的可关联性访问副本和删除证据。","evidence":"逐项回到目的、可关联性、访问、派生副本和删除证据"},"interpretation":{"answer":"加密保护传输存储，不限制解密后的用途与访问。","evidence":"不限制解密后的合法账户滥用"},"boundary":{"answer":"辨析结论不替代法律判断和完整攻击验证。","evidence":"不替代具体法律判断或对完整系统的攻击验证"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>画出端到端个人数据流和信任边界；区分泄露、成员推断与目的外使用；计算组合查询的隐私预算；设计删除、审计和供应商控制；理解隐私—效用边界而非承诺零风险。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先问数据能否关联到人，而不只找姓名和手机号<span class=\"dd-badge intuition\">问题定义</span></h2><p class=\"dd-lead\">删掉直接标识符后，诊疗记录是否就成了匿名数据？</p><p>直接标识符只是最明显的一层。年龄、邮编、罕见病、时间戳、设备指纹与对话内容可形成准标识符，和外部数据联结后重新识别个人。隐私风险还包括模型替用户推断敏感属性、把数据用于原同意范围之外的目的，以及让没有业务需要的人访问。</p><p>因此资产清单要记录数据主体、敏感度、用途、法律/合同依据、保存期和可接收方；“已脱敏”必须说明攻击者知识和验证方法，不能作为永久属性。</p><p>隐私识别输入数据字段、外部可联结信息、处理目的和可访问者，输出直接标识符、准标识符、敏感推断与目的外使用风险。删掉姓名只移除最明显线索，年龄邮编罕见病和时间仍可能组合重识别；资产清单还要记录主体、用途、依据、保存期和接收方。“已脱敏”只能相对明确攻击者知识和测试成立。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>隐私威胁分布在训练、推理和运营三条路径<span class=\"dd-badge eng\">威胁模型</span></h2><p class=\"dd-lead\">模型没有直接打印个人信息，系统仍可能怎样伤害隐私？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>路径</th><th>风险</th><th>证据</th></tr></thead><tbody><tr><td>训练</td><td>记忆罕见序列、成员推断、数据集来源越权</td><td>抽取测试、成员攻击、数据谱系</td></tr><tr><td>推理</td><td>提示和RAG文档发给越界提供方、跨租户检索</td><td>网络流、租户ACL、供应商记录</td></tr><tr><td>运营</td><td>日志、追踪、人工标注和备份形成新副本</td><td>保留策略、访问日志、删除回执</td></tr><tr><td>输出</td><td>真实敏感信息泄露或从非敏感输入推断属性</td><td>金丝雀测试、逐字段授权</td></tr></tbody></table></div><p>“模型层安全”不能覆盖日志与供应链；同样，输出过滤也不能撤回已经发送给第三方的提示。</p><p>威胁建模输入训练、推理、运营和输出各阶段的数据副本与主体，输出记忆抽取、成员推断、跨租户检索、日志泄露或敏感属性推断等攻击路径。沿数据实际流向检查供应商、缓存、标注和备份，分别记录攻击前提与验证证据。模型没有直接打印姓名不表示上游复制和目的外使用没有发生。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：客服摘要从工单到外部模型再回到工单<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">一条含身份证号和病史的工单，哪些副本最容易被清单漏掉？</p><ol class=\"dd-steps\"><li>浏览器提交原工单，接入层先按用途分离账号标识和正文。</li><li>本地识别直接标识符并以短期令牌替换；映射表留在受控域。</li><li>检索层只取该租户、该坐席有权查看的最小段落。</li><li>发送给模型的负载记录字段清单、区域、保留和训练使用约定，不记录正文到通用遥测。</li><li>输出回填令牌前再次做授权和敏感属性检查。</li><li>追踪只保存哈希请求ID、模型版本和策略结果；受限故障库单独保存必要样本。</li><li>删除请求沿工单、缓存、向量索引、日志、标注集和备份清单传播，并产生逐站回执。</li></ol><p>如果只在第六步过滤输出，前五步的数据出境、跨租户和目的外使用风险都没有解决。</p><p>客服案例输入含身份证号和病史的工单、租户权限、外部模型和删除请求，输出最小化负载、受控令牌映射、授权结果、审计元数据与逐站删除回执。先在本地域替换标识，再只检索有权段落，外发前记录字段和保留约定，回填前再次授权；删除沿缓存向量日志标注备份传播。只在输出端过滤不能撤回前面已经越界的数据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>差分隐私用受控噪声限制单条记录的边际影响<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">为什么“加一点噪声”需要预算，而不是随意扰动？</p><p>差分隐私比较只相差一人的相邻数据集，要求任一输出事件的概率比不超过 <code>e^ε</code>（另允许小概率 <code>δ</code>）。ε 越小，攻击者越难判断某人是否参与，但统计效用通常更低。</p><p>若三个串行查询分别消耗 ε=0.4、0.3、0.2，在基本组合上总预算至多为 <b>0.9</b>，不是仍为0.4；每天重跑会继续累计。预算必须绑定数据集、主体范围和时间窗，由账户器拒绝超额查询。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"基本组合下的总隐私预算\"><mi>εtotal</mi><mo>≤</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>ε</mi><mi>i</mi></msub><mo>=</mo><mn>0.4</mn><mo>+</mo><mn>0.3</mn><mo>+</mo><mn>0.2</mn><mo>=</mo><mn>0.9</mn></math></div><p>差分隐私保护参与性，不自动保证授权、数据准确性或输出无歧视。</p><p>差分隐私预算输入相邻数据集、每次查询预算 εi、允许的小概率例外 δ 和时间范围，输出组合隐私预算 εtotal 与是否允许继续查询。它解决重复发布带噪统计时隐私泄露如何累计的问题。基本组合把同一数据集上的 εi 相加，0.4+0.3+0.2 得 0.9；ε 越小通常保护更强但统计噪声更大。预算限制单条记录对输出分布的边际影响，不替代访问授权、准确性或公平性。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：每越过一道信任边界，都要减少数据并留下证据<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">怎样一眼发现“删除只做了主库、日志和向量库没删”的缺口？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"个人数据从采集经过最小化、权限检索、模型提供方、日志和输出的流向及删除回执\"><defs><marker id=\"pv30\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6z\" fill=\"#7f8b9d\"/></marker></defs><rect x=\"20\" y=\"90\" width=\"112\" height=\"92\" rx=\"10\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"76\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\">原始工单</text><text x=\"76\" y=\"145\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">身份+正文</text><path d=\"M132 136H172\" stroke=\"#7f8b9d\" marker-end=\"url(#pv30)\"/><rect x=\"177\" y=\"65\" width=\"125\" height=\"142\" rx=\"10\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"239\" y=\"96\" text-anchor=\"middle\" class=\"svg-t\">受控域</text><text x=\"239\" y=\"123\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">目的/最小化</text><text x=\"239\" y=\"147\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">令牌映射</text><text x=\"239\" y=\"175\" text-anchor=\"middle\" class=\"svg-t\">租户 ACL</text><path d=\"M302 136H342\" stroke=\"#7f8b9d\" marker-end=\"url(#pv30)\"/><rect x=\"347\" y=\"65\" width=\"125\" height=\"142\" rx=\"10\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"409\" y=\"96\" text-anchor=\"middle\" class=\"svg-t\">模型边界</text><text x=\"409\" y=\"123\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">必要字段</text><text x=\"409\" y=\"147\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">区域/保留</text><text x=\"409\" y=\"175\" text-anchor=\"middle\" class=\"svg-t\">禁止再训练</text><path d=\"M472 136H512\" stroke=\"#7f8b9d\" marker-end=\"url(#pv30)\"/><rect x=\"517\" y=\"65\" width=\"125\" height=\"142\" rx=\"10\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"579\" y=\"96\" text-anchor=\"middle\" class=\"svg-t\">输出与追踪</text><text x=\"579\" y=\"123\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">再授权/过滤</text><text x=\"579\" y=\"147\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">元数据日志</text><text x=\"579\" y=\"175\" text-anchor=\"middle\" class=\"svg-t\">受限故障库</text><path d=\"M642 136H690\" stroke=\"#7f8b9d\" marker-end=\"url(#pv30)\"/><text x=\"716\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\">用户</text><path d=\"M716 180V268H78V190\" fill=\"none\" stroke=\"#cf7c72\" stroke-dasharray=\"6 5\" marker-end=\"url(#pv30)\"/><text x=\"395\" y=\"291\" text-anchor=\"middle\" class=\"svg-t\">删除请求：主库 → 缓存 → 向量 → 日志 → 标注 → 备份回执</text><text x=\"395\" y=\"316\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">任一站无所有者或无可验证回执，删除就不完整</text></svg><figcaption>图 1　隐私控制沿数据流部署；末端过滤不能修复上游越界复制。</figcaption></figure><p>信任边界图输入数据从原始工单到受控域、模型方、输出追踪和删除链路的节点与副本，输出每次跨边界所需的最小化、授权、保留和回执控制。沿箭头逐站核对字段、所有者和删除状态，任一无负责人或无回执节点就是缺口。图只帮助发现数据流断点，不能替代实际网络日志和删除回放。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>最小化同时约束字段、精度、人数和保存时间<span class=\"dd-badge eng\">控制设计</span></h2><p class=\"dd-lead\">业务说“以后可能有用”，为什么不是无限保留的理由？</p><p>最小化不是简单删列，而是对任务逐项证明必要性：能用年龄段就不用生日，能用聚合统计就不传逐人记录，能在本地计算就不上传，能短期缓存就不写永久日志。训练、调试、产品分析和安全调查是不同目的，应分别授权和保存。</p><p>上线前用字段消融验证删掉某字段对任务质量的真实影响；如果收益微小而识别风险大，就不应收集。默认拒绝新下游用途，新增用途需要重新评估而非继承旧同意。</p><p>数据最小化输入任务目的、候选字段、精度、主体人数、保存时长和效用实验，输出保留、泛化、本地计算、聚合或删除决定。逐字段消融验证必要性：能用年龄段就不用生日，收益微小而识别风险大就不收集；训练调试分析各自单独授权。未来可能有用不是无限保存的目的，新用途必须重新评估。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>访问控制必须跟随检索结果和工具动作<span class=\"dd-badge eng\">权限边界</span></h2><p class=\"dd-lead\">用户能问模型，不等于模型能代表用户读取所有文档。</p><p>RAG 在召回前执行主体、租户、文档和字段级权限，不能先全库检索再在生成后遮盖；嵌入和缓存也要隔离租户。Agent 调工具时用短期、窄范围身份，每次写操作重新校验，防止提示注入把合法会话变成越权通道。</p><p>对管理员、开发者、人工审核者分别定义用途和可见字段，敏感访问需理由、审批与不可变日志。抽样检查“谁在何时因何目的看了什么”，比只检查角色名称更接近真实风险。</p><p>权限控制输入当前主体、租户、资源、字段、动作和短期凭证，输出允许的检索候选、工具调用与不可变审计记录。RAG 在召回前过滤允许域，返回和写操作时再次按权威状态鉴权；缓存与嵌入也按租户隔离。用户能提问不代表代理能读取全库，提示注入也不能扩大身份权限。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>删除要求建立可追踪谱系，模型权重是最难的一站<span class=\"dd-badge eng\">生命周期</span></h2><p class=\"dd-lead\">从数据库删掉一行，为什么不能立刻声称“已被遗忘”？</p><p>记录从原始对象到清洗集、训练切片、嵌入、缓存、标注任务、检查点和备份的派生关系。可直接删除的存储要给完成回执；不可立即重写的备份要冻结恢复后的再删除流程并说明期限。若数据已进入模型权重，删除单样本的效果难以证明，可能需要重训、机器遗忘或风险隔离。</p><p>对用户应准确说明已删除、排队删除、仅停止继续使用和技术上尚不能验证的部分，不能把“从产品界面消失”表述为全链路清除。</p><p>删除谱系输入原始对象及其清洗集、训练切片、嵌入、缓存、标注、检查点和备份派生关系，输出已删除、排队删除、停止使用或暂不可验证的逐站状态。可删存储返回完成回执，备份规定恢复后再删除，权重中的单样本影响可能需重训或机器遗忘验证。界面消失不等于全链路遗忘。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>隐私评测要模拟有辅助信息的攻击者<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">随机抽查输出没看到手机号，能证明系统安全吗？</p><p>建立罕见金丝雀、训练数据抽取、成员推断、属性推断、跨租户检索、日志访问和删除回放测试；攻击者可知道部分姓名、模板或文档结构。报告按数据敏感度切片的攻击成功率、暴露人数、每人字段数、访问时长和删除完成率。</p><p>输出 PII 精确率/召回率只是其中一层。过度过滤会破坏正常地址或医学内容，所以还要测误拦、业务效用与人工恢复成本；任何单个“隐私分数”都不应掩盖高影响尾部事件。</p><p>隐私评测输入敏感切片、攻击者辅助知识、训练抽取、成员与属性推断、跨租户访问和删除回放，输出攻击成功率、暴露人数字段、访问时长、误拦和删除完成率。测试应模拟攻击者已知部分模板或身份线索，而非只随机扫手机号；按高影响尾部事件单独报告。一个汇总隐私分数不能掩盖罕见但严重泄露。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>供应商契约和实际网络流必须一致<span class=\"dd-badge eng\">供应链</span></h2><p class=\"dd-lead\">合同写“不用于训练”，怎样证明运行时真的遵守？</p><p>确认子处理方、处理区域、传输和静态加密、密钥控制、默认保留、滥用监测留存、事件通知、删除接口和退出时数据可移植性。再用网络代理、审计日志和抽样请求核对实际发送字段与声明，不让 SDK 遥测悄悄多传。</p><p>供应商模型或条款变化触发再评估；无法提供证据时限制数据类别或切换本地方案。自托管减少外部传输，却增加补丁、备份、内部滥用和密钥管理责任，不等于自动合规。</p><p>供应商验证输入合同条款、子处理方、区域、字段、保留、训练使用、加密密钥和删除接口，输出声明与实际网络流的一致性证据。用代理与审计日志抽样核对 SDK 真正发送的字段，模型或条款变化触发再评估；无法举证就限制数据或更换方案。自托管减少外传，却增加内部权限、补丁、备份和密钥责任。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>隐私与可观测性不是二选一，而是分层留证<span class=\"dd-badge eng\">工程权衡</span></h2><p class=\"dd-lead\">完全不记录请求，事故发生后如何查清影响范围？</p><p>常规遥测保存请求ID、策略版本、模型、时延、token量和风险标签，不保存正文；只有满足明确触发条件的故障样本进入隔离库，字段先最小化，访问需审批并有短保留期。高敏场景可用本地统计、聚合指标和受控重放替代原文日志。</p><p>审计需要“谁做了什么”的证据，不一定需要复制全部内容。若确需全文，必须把调试目的、人数、期限、环境与删除机制写成独立控制。</p><p>隐私误区辨析是把常见控制声明映射到实际覆盖与残余风险的方法。它解决这些局部控制为何不能成为完整隐私保证的问题。辨析输入“去姓名、加密、不训练、本地部署、输出过滤、删除主库”等隐私声明，输出该声明真正覆盖的风险与仍未覆盖的数据流。逐项回到目的、可关联性、访问、派生副本和删除证据：加密只保护传输存储，不限制解密后的合法账户滥用。结论用于纠正控制范围，不替代具体法律判断或对完整系统的攻击验证。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">12</span>常见误区与概念依赖<span class=\"dd-badge intuition\">误区与学习路线</span></h2><p class=\"dd-lead\">隐私的核心不是把敏感词遮住，而是控制可关联的数据处理。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>匿名化不是去掉姓名；加密保护传输和存储，不限制合法解密后的用途；差分隐私不替代访问授权。</div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>只要不训练就无隐私风险</td><td>提示、检索、日志和人工审核仍会复制数据</td></tr><tr><td>本地部署天然安全</td><td>外传减少，但内部权限、备份和漏洞仍在</td></tr><tr><td>输出过滤等于保护隐私</td><td>数据可能在输出前已越过边界</td></tr><tr><td>删除主库即完成</td><td>还需派生物、备份和权重层证据</td></tr></tbody></table></div><p><b>学习路线：</b>先学数据治理、身份与访问控制，再学差分隐私、成员推断和机器遗忘；工程上连接RAG权限、可观测性、供应商管理与事件响应。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义数据主体、目的与不可接受影响</li><li>枚举直接/准标识符和攻击者知识</li><li>画出采集到删除的全部副本与边界</li><li>逐站最小化并绑定租户权限</li><li>选择去标识、聚合或差分隐私控制</li><li>验证供应商契约与实际网络流</li><li>用攻击模拟和删除回放验收</li><li>持续监控用途漂移并回应主体权利</li></ol>\n      <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>验证层</th><th>在“AI 隐私：沿数据流控制可识别性、记忆与越权使用”中固定什么</th><th>观察什么证据</th></tr></thead><tbody>\n      <tr><td>输入</td><td>同一批样本、前处理与权限边界</td><td>输入哈希、切片标签和拒绝原因</td></tr>\n      <tr><td>机制</td><td>仅改变一个核心变量，其余配置锁定</td><td>关键中间状态及首次偏离预期的位置</td></tr>\n      <tr><td>输出</td><td>同一验收规则与资源预算</td><td>质量、成本、延迟和失败率的分层差异</td></tr>\n      <tr><td>反证</td><td>保留不启用目标机制的对照组</td><td>收益是否跨样本与随机种子稳定复现</td></tr>\n      </tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么删掉姓名仍可能识别人？</li><li>三个差分隐私查询为何要组合预算？</li><li>输出过滤不能解决什么？</li><li>怎样证明删除完成？</li><li>隐私日志怎样兼顾审计？</li><li>假设“AI 隐私：沿数据流控制可识别性、记忆与越权使用”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>准标识符可与外部信息组合，罕见属性和时间地点也会缩小候选。</li><li>同一数据集的重复观察会累积信息泄露，基本组合上ε相加。</li><li>不能撤回已经发给供应商、写入日志或跨租户召回的数据。</li><li>依靠覆盖主库、派生物、向量、缓存、日志、标注和备份的谱系及逐站回执。</li><li>默认留元数据，正文进入目的明确、隔离、短期且受审批的故障库。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://www.nist.gov/privacy-framework/privacy-framework\" target=\"_blank\" rel=\"noopener\">NIST Privacy Framework 1.1</a>：组织隐私风险管理与数据处理生态</li><li><a href=\"https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf\" target=\"_blank\" rel=\"noopener\">The Algorithmic Foundations of Differential Privacy</a>：差分隐私定义、组合与机制</li><li><a href=\"https://arxiv.org/abs/2012.07805\" target=\"_blank\" rel=\"noopener\">Extracting Training Data from Large Language Models</a>：语言模型记忆与训练数据抽取</li><li><a href=\"https://arxiv.org/abs/1610.05820\" target=\"_blank\" rel=\"noopener\">Membership Inference Attacks</a>：成员推断威胁模型</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
